struct Node;

/// Last second of 9999-12-31, the latest instant whose date fits `YYYY-MM-DD`.
const MAX_SECONDS: u64 = 253_402_300_799;

/// Percent-encode everything outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Convert seconds since the Unix epoch to a `YYYY-MM-DD` string (always 10 bytes).
fn civil_date(seconds: u64) -> String {
    let secs = if seconds > MAX_SECONDS { MAX_SECONDS } else { seconds };
    let days = secs / 86_400;

    // Days-to-civil conversion (proleptic Gregorian calendar).
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z % 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }

    let date = format!("{:04}-{:02}-{:02}", year, month, day);
    if date.len() == 10 {
        date
    } else {
        // Unreachable given the clamp above; kept so the contract holds regardless.
        String::from("9999-12-31")
    }
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch under the extended grant (aap:caps/http-client@0.1.0).
        // `fetch` returns transport failures as a value, so a failed fetch
        // cannot change the node's output; the record is deliberately unused.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let now = crate::wasi::clocks::wall_clock::now();

        RunInfo {
            date: civil_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
```

